    int constant MIN_HOLDER_OUTPUT_SOMPI = 50000000;
    int constant MAX_MERGE_INPUTS = 8;
    byte[32] constant PLATFORM_PROTOCOL_FEE_RECIPIENT = 0xce2100e68197c8e695bd781d07e2bd5de7ed77f5a97668884190531bdc632c01;

    byte[32] ownerIdentifier = stateOwner;
    int identifierType = stateOwnerType;
    int amount = stateAmount;
    int minterMode = mintMode;
    int mintPriceSompi = mintPricePerTokenSompi;
    byte[32] treasury = treasuryRecipient;
    byte[32] feeRecipient = PLATFORM_PROTOCOL_FEE_RECIPIENT;
    int feeBps = protocolFeeBps;
    byte[32] ticker = tokenTicker;
    byte[32] name = tokenName;
    int priceScale = tokenDisplayScale;

    function requireOwnerType(int t) {
        require(t == OWNER_PUBKEY || t == OWNER_SCRIPT_HASH || t == OWNER_COVENANT_ID);
    }

    function requireHolder() {
        require(minterMode == MODE_HOLDER);
        requireOwnerType(identifierType);
        require(amount > 0);
        require(priceScale > 0);
    }

    function requireMinter() {
        require(minterMode == MODE_CONTROLLED || minterMode == MODE_PUBLIC);
        require(identifierType == OWNER_PUBKEY);
        require(amount > 0);
        require(mintPriceSompi >= 0);
        require(priceScale > 0);
        require(feeBps >= 0);
        require(feeBps <= FEE_DENOMINATOR_BPS);
    }

    function validateTokenOutput(byte[32] outOwner, int outOwnerType, int outAmount, int outputIndex) {
        requireOwnerType(outOwnerType);
        require(tx.outputs[outputIndex].value >= MIN_HOLDER_OUTPUT_SOMPI);
        validateOutputState(outputIndex, {
            ownerIdentifier: outOwner,
            identifierType: outOwnerType,
            amount: outAmount,
            minterMode: MODE_HOLDER,
            mintPriceSompi: mintPriceSompi,
            treasury: treasury,
            feeRecipient: feeRecipient,
            feeBps: feeBps,
            ticker: ticker,
            name: name,
            priceScale: priceScale
        });
    }

    function validateMinterOutput(int remainingAmount, int outputIndex) {
        validateOutputState(outputIndex, {
            ownerIdentifier: ownerIdentifier,
            identifierType: identifierType,
            amount: remainingAmount,
            minterMode: minterMode,
            mintPriceSompi: mintPriceSompi,
            treasury: treasury,
            feeRecipient: feeRecipient,
            feeBps: feeBps,
            ticker: ticker,
            name: name,
            priceScale: priceScale
        });
    }

    function exactMintGrossSompi(int rawAmount, int displayUnitPrice): int {
        require(rawAmount >= 0);
        require(displayUnitPrice >= 0);
        require(priceScale > 0);
        int wholeAmount = rawAmount / priceScale;
        int fractionAmount = rawAmount - wholeAmount * priceScale;
        int grossWholeSompi = wholeAmount * displayUnitPrice;
        int fractionProduct = fractionAmount * displayUnitPrice;
        int grossFractionSompi = fractionProduct / priceScale;
        require(grossFractionSompi * priceScale == fractionProduct);
        return(grossWholeSompi + grossFractionSompi);
    }

    function requireMintPayment(int tokenAmount, int treasuryOutputIndex, int feeOutputIndex) {
        if (mintPriceSompi > 0) {
            int gross = exactMintGrossSompi(tokenAmount, mintPriceSompi);
            require(gross >= MIN_PROTOCOL_FEE_SOMPI);
            int fee = gross * feeBps / FEE_DENOMINATOR_BPS;
            if (fee < MIN_PROTOCOL_FEE_SOMPI) {
                fee = MIN_PROTOCOL_FEE_SOMPI;
            }
            int treasuryNet = gross - fee;
            if (treasuryNet > 0) {
                require(tx.outputs[treasuryOutputIndex].value == treasuryNet);
                require(tx.outputs[treasuryOutputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(treasury))));
            }
            if (fee > 0) {
                require(tx.outputs[feeOutputIndex].value == fee);
                require(tx.outputs[feeOutputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(feeRecipient))));
            }
        }
    }

    function requireTransferAuth(int witness) {
        if (identifierType == OWNER_SCRIPT_HASH) {
            require(tx.inputs[witness].scriptPubKey == byte[](new ScriptPubKeyP2SH(ownerIdentifier)));
        } else {
            require(identifierType == OWNER_COVENANT_ID);
            require(OpInputCovenantId(witness) == ownerIdentifier);
        }
    }

    entrypoint function transferByOwnerSig(sig ownerSig, byte[32] toOwner, int toOwnerType, int tokenAmount, int toOutputIndex, int changeOutputIndex) {
        requireHolder();
        require(identifierType == OWNER_PUBKEY);
        require(checkSig(ownerSig, pubkey(ownerIdentifier)));
        transfer(toOwner, toOwnerType, tokenAmount, toOutputIndex, changeOutputIndex);
    }

    entrypoint function transferByWitness(int witness, byte[32] toOwner, int toOwnerType, int tokenAmount, int toOutputIndex, int changeOutputIndex) {
        requireHolder();
        requireTransferAuth(witness);
        transfer(toOwner, toOwnerType, tokenAmount, toOutputIndex, changeOutputIndex);
    }

    function transfer(byte[32] toOwner, int toOwnerType, int tokenAmount, int toOutputIndex, int changeOutputIndex) {
        require(tokenAmount > 0);
        require(tokenAmount <= amount);
        validateTokenOutput(toOwner, toOwnerType, tokenAmount, toOutputIndex);
        if (tokenAmount < amount) {
            require(OpAuthOutputCount(this.activeInputIndex) == 2);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == toOutputIndex);
            require(OpAuthOutputIdx(this.activeInputIndex, 1) == changeOutputIndex);
            validateTokenOutput(ownerIdentifier, identifierType, amount - tokenAmount, changeOutputIndex);
        } else {
            require(OpAuthOutputCount(this.activeInputIndex) == 1);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == toOutputIndex);
        }
    }

    entrypoint function mintByAuthoritySig(sig authoritySig, byte[32] toOwner, int toOwnerType, int tokenAmount, int tokenOutputIndex, int minterOutputIndex, int treasuryOutputIndex, int feeOutputIndex) {
        requireMinter();
        require(minterMode == MODE_CONTROLLED);
        require(checkSig(authoritySig, pubkey(ownerIdentifier)));
        mint(toOwner, toOwnerType, tokenAmount, tokenOutputIndex, minterOutputIndex, treasuryOutputIndex, feeOutputIndex);
    }

    entrypoint function mintPublic(byte[32] toOwner, int toOwnerType, int tokenAmount, int tokenOutputIndex, int minterOutputIndex, int treasuryOutputIndex, int feeOutputIndex) {
        requireMinter();
        require(minterMode == MODE_PUBLIC);
        mint(toOwner, toOwnerType, tokenAmount, tokenOutputIndex, minterOutputIndex, treasuryOutputIndex, feeOutputIndex);
    }

    function mint(byte[32] toOwner, int toOwnerType, int tokenAmount, int tokenOutputIndex, int minterOutputIndex, int treasuryOutputIndex, int feeOutputIndex) {
        require(tokenAmount > 0);
        require(tokenAmount <= amount);
        requireMintPayment(tokenAmount, treasuryOutputIndex, feeOutputIndex);
        validateTokenOutput(toOwner, toOwnerType, tokenAmount, tokenOutputIndex);
        if (tokenAmount < amount) {
            require(OpAuthOutputCount(this.activeInputIndex) == 2);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == tokenOutputIndex);
            require(OpAuthOutputIdx(this.activeInputIndex, 1) == minterOutputIndex);
            validateMinterOutput(amount - tokenAmount, minterOutputIndex);
        } else {
            require(OpAuthOutputCount(this.activeInputIndex) == 1);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == tokenOutputIndex);
        }
    }

    entrypoint function burnByOwnerSig(sig ownerSig, int tokenAmount, int changeOutputIndex) {
        requireHolder();
        require(identifierType == OWNER_PUBKEY);
        require(checkSig(ownerSig, pubkey(ownerIdentifier)));
        require(tokenAmount > 0);
        require(tokenAmount <= amount);
        if (tokenAmount < amount) {
            require(OpAuthOutputCount(this.activeInputIndex) == 1);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == changeOutputIndex);
            validateTokenOutput(ownerIdentifier, identifierType, amount - tokenAmount, changeOutputIndex);
        } else {
            require(OpAuthOutputCount(this.activeInputIndex) == 0);
        }
    }

    function requireMergePeerState(State peer) {
        require(peer.ownerIdentifier == ownerIdentifier);
        require(peer.identifierType == identifierType);
        require(peer.amount > 0);
        require(peer.minterMode == MODE_HOLDER);
        require(peer.mintPriceSompi == mintPriceSompi);
        require(peer.treasury == treasury);
        require(peer.feeRecipient == feeRecipient);
        require(peer.feeBps == feeBps);
        require(peer.ticker == ticker);
        require(peer.name == name);
        require(peer.priceScale == priceScale);
    }

    entrypoint function mergeByOwnerSig(sig ownerSig) {
        requireHolder();
        require(identifierType == OWNER_PUBKEY);
        require(checkSig(ownerSig, pubkey(ownerIdentifier)));

        byte[32] covenantId = OpInputCovenantId(this.activeInputIndex);
        int inputCount = OpCovInputCount(covenantId);
        require(inputCount >= 2);
        require(inputCount <= MAX_MERGE_INPUTS);
        require(OpCovInputIdx(covenantId, 0) == this.activeInputIndex);

        int mergedAmount = 0;
        int inputSompi = 0;
        for(i, 0, inputCount, MAX_MERGE_INPUTS) {
            int inputIndex = OpCovInputIdx(covenantId, i);
            State inputState = readInputState(inputIndex);
            requireMergePeerState(inputState);
            require(tx.inputs[inputIndex].value >= MIN_HOLDER_OUTPUT_SOMPI);

            int nextAmount = mergedAmount + inputState.amount;
            int nextInputSompi = inputSompi + tx.inputs[inputIndex].value;
            require(nextAmount > mergedAmount);
            require(nextInputSompi > inputSompi);
            mergedAmount = nextAmount;
            inputSompi = nextInputSompi;
        }

        require(OpCovOutputCount(covenantId) == 1);
        require(OpCovOutputIdx(covenantId, 0) == 0);
        require(OpAuthOutputCount(this.activeInputIndex) == 1);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == 0);
        validateTokenOutput(ownerIdentifier, identifierType, mergedAmount, 0);
        require(tx.outputs[0].value == MIN_HOLDER_OUTPUT_SOMPI);

        int refundSompi = inputSompi - MIN_HOLDER_OUTPUT_SOMPI;
        require(refundSompi >= MIN_HOLDER_OUTPUT_SOMPI);
        require(tx.outputs[1].value == refundSompi);
        require(tx.outputs[1].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(ownerIdentifier))));
    }

    entrypoint function mergePeerByOwnerSig(sig ownerSig, int primaryInputIndex, int mergedAmount) {
        requireHolder();
        require(identifierType == OWNER_PUBKEY);
        require(checkSig(ownerSig, pubkey(ownerIdentifier)));

        byte[32] covenantId = OpInputCovenantId(this.activeInputIndex);
        int inputCount = OpCovInputCount(covenantId);
        require(inputCount >= 2);
        require(inputCount <= MAX_MERGE_INPUTS);
        require(primaryInputIndex == OpCovInputIdx(covenantId, 0));
        require(primaryInputIndex != this.activeInputIndex);
        require(tx.inputs[this.activeInputIndex].value >= MIN_HOLDER_OUTPUT_SOMPI);

        State primary = readInputState(primaryInputIndex);
        requireMergePeerState(primary);
        int minimumMergedAmount = amount + primary.amount;
        require(minimumMergedAmount > amount);
        require(mergedAmount >= minimumMergedAmount);
        require(OpAuthOutputCount(this.activeInputIndex) == 0);
        require(OpCovOutputCount(covenantId) == 1);
        require(OpCovOutputIdx(covenantId, 0) == 0);
        validateTokenOutput(ownerIdentifier, identifierType, mergedAmount, 0);
        require(tx.outputs[0].value == MIN_HOLDER_OUTPUT_SOMPI);
        require(tx.outputs[1].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(ownerIdentifier))));
    }
}
